const events = ["e1", "e2", "e3", "e4", "e5"];
function serve(fromIdx) { return events.slice(fromIdx); }
let idx = 0;
const first = serve(idx); idx = 2; // 只处理到 e3（下标2）就断开
console.log("首次收到:", first.slice(0, 3).join(","), "(在 e3 后断开)");
const replay = serve(idx + 1); // 从 e4 续传
console.log("重连续传:", replay.join(","));
console.log("合计去重:", first.slice(0, 3).concat(replay).length, "条");
